(async()=>{try{const response=await fetch('/api/content',{cache:'no-store'});if(!response.ok)return;const {data}=await response.json();for(const el of document.querySelectorAll('[data-content]')){const key=el.dataset.content,value=data[key];if(typeof value!=='string')continue;if(key==='general.description'){el.setAttribute('content',value)}else if(key==='contact.line_url'||key==='contact.map_url'){el.href=value}else if(el.tagName==='IMG'){el.src=value}else if(key.startsWith('contact.phone_')){el.textContent=value+' ↗';el.href='tel:'+value.replace(/[^+0-9]/g,'')}else{el.textContent=value}}document.dispatchEvent(new Event('site-content-loaded'))}catch{}})();
